54	/* A disc wider than the cached rows, with the same arithmetic, drawn through
55	 * fill_box so it blends or sets mask bits like the rest of its shape. Only
56	 * the rows on the canvas are worked out. */
57	static void wide_disc_rows(Canvas *c, wide_t x, wide_t y, int w, uint16_t colour) {
58	  const double centre = (w - 1) / 2.0, radius = w / 2.0;
59	  const wide_t first = max_w(0, -y), last = min_w(w - 1, (wide_t)c->h - 1 - y);
60	  for (wide_t row = first; row <= last; row++) {
61	    const double ny = ((double)row - centre) / radius;
62	    const double t = 1.0 - ny * ny;
63	    if (t < 0) continue;
64	    const double half = radius * sqrt(t);
65	    const wide_t xa = (wide_t)ceil(centre - half), xb = (wide_t)floor(centre + half);
66	    if (xb >= xa) fill_box(c, x + xa, y + row, x + xb, y + row, colour);
67	  }
68	}
