70	/* A disc of diameter w centred on the pixel (cx, cy). Skipped when it cannot
71	 * reach the canvas. */
72	static void disc(Canvas *c, wide_t cx, wide_t cy, int w, uint16_t colour) {
73	  if (cx < -(wide_t)w || cy < -(wide_t)w || cx > (wide_t)c->w + w ||
74	      cy > (wide_t)c->h + w)
75	    return;
76	  const wide_t x = cx - w / 2, y = cy - w / 2;
77	  if (w > DISC_MAX_W && g_alpha) {
78	    wide_disc_rows(c, x, y, w, colour);
79	    return;
80	  }
81	  if (w < 1 || w > DISC_MAX_W) {
82	    canvas_fill_ellipse(c, (int)x, (int)y, w, w, colour);
83	    return;
84	  }
85	  if (!g_disc_built[w]) build_disc(w);
86	  for (int row = 0; row < w; row++) {
87	    const disc_row d = g_disc_rows[w][row];
88	    if (d.xb >= d.xa) fill_box(c, x + d.xa, y + row, x + d.xb, y + row, colour);
89	  }
90	}
