100	/* The canvas holds byte-swapped RGB565, so each pixel is swapped to blend and
101	 * swapped back. The box is already clipped. */
102	static void blend_box(Canvas *c, int x, int y, int w, int h, uint16_t colour) {
103	  const uint32_t src = spread(swap16(colour));
104	  const uint32_t a = (uint32_t)g_alpha;
105	  for (int yy = y; yy < y + h; yy++) {
106	    uint16_t *row = c->px + (size_t)yy * c->w + x;
107	    for (int i = 0; i < w; i++) {
108	      const uint32_t dst = spread(swap16(row[i]));
109	      row[i] = swap16(unspread((((src - dst) * a >> 5) + dst) & SPREAD_MASK));
110	    }
111	  }
112	  canvas_mark_dirty(c, x, y, w, h);
113	}
