115	/* A shape made of overlapping pieces (a polyline's segments and joins, a
116	 * round cap and its segment) would blend twice where they overlap. While a
117	 * mask is open, pieces only set bits in it, one per pixel of the canvas, and
118	 * close_mask blends each set pixel once. */
119	static uint32_t *g_mask;
120	static int g_mask_words;
121	
122	static void open_mask(const Canvas *c) {
123	  g_mask_words = (c->w + 31) / 32;
124	  g_mask = (uint32_t *)calloc((size_t)g_mask_words * (size_t)c->h, sizeof(uint32_t));
125	}
126	
127	static void mask_row(int y, int x0, int x1) {
128	  uint32_t *row = g_mask + (size_t)y * g_mask_words;
129	  for (int w = x0 / 32; w <= x1 / 32; w++) {
130	    const int lo = w == x0 / 32 ? x0 % 32 : 0;
131	    const int hi = w == x1 / 32 ? x1 % 32 : 31;
132	    const uint32_t bits = (hi == 31 ? ~0u : (1u << (hi + 1)) - 1u) & (~0u << lo);
133	    row[w] |= bits;
134	  }
135	}
