307	/* One slanted segment whose ends can be anywhere in the int range. Ends cut by
308	 * the clip are off screen anyway. */
309	static void slanted(Canvas *c, wide_t ix1, wide_t iy1, wide_t ix2, wide_t iy2,
310	                    int cap1, int cap2, int w, uint16_t colour) {
311	  /* The clip is in double, which the S3 does in software, and floats are exact
312	   * well past any canvas, so only ends far outside need it. */
313	  const wide_t near = (wide_t)1 << 20;
314	  const int small = ix1 > -near && ix1 < near && iy1 > -near && iy1 < near &&
315	                    ix2 > -near && ix2 < near && iy2 > -near && iy2 < near;
316	  const float o = centre_offset(w);
317	  if (small) {
318	    /* Straight from int: an int under 2^20 is exact as a float, so this is
319	     * what the double detour gave, without four int64-to-double and four
320	     * double-to-float calls a segment. */
321	    segment_quad(c, (vec2){(float)(int)ix1 + o, (float)(int)iy1 + o},
322	                 (vec2){(float)(int)ix2 + o, (float)(int)iy2 + o}, cap1, cap2, w, colour);
323	    return;
324	  }
325	  double x1 = (double)ix1, y1 = (double)iy1, x2 = (double)ix2, y2 = (double)iy2;
326	  if (!clip_to_canvas(c, (wide_t)w + 2, &x1, &y1, &x2, &y2)) return;
327	  segment_quad(c, (vec2){(float)x1 + o, (float)y1 + o},
328	               (vec2){(float)x2 + o, (float)y2 + o}, cap1, cap2, w, colour);
329	}
