331	static void segment_pieces(Canvas *c, const struct XshimGC *gc, int x1, int y1,
332	                           int x2, int y2, int cap_start, int cap_end) {
333	  const int w = gc->line_width;
334	  const uint16_t colour = (uint16_t)gc->foreground;
335	
336	  if (cap_start == CapRound) disc(c, x1, y1, w, colour);
337	  if (cap_end == CapRound) disc(c, x2, y2, w, colour);
338	
339	  if (x1 == x2 && y1 == y2) {
340	    if (cap_start == CapProjecting || cap_end == CapProjecting)
341	      axis_aligned(c, x1, y1, x2, y2, cap_start, cap_end, w, colour);
342	    return;
343	  }
344	  if (x1 == x2 || y1 == y2)
345	    axis_aligned(c, x1, y1, x2, y2, cap_start, cap_end, w, colour);
346	  else
347	    slanted(c, x1, y1, x2, y2, cap_start, cap_end, w, colour);
348	}
