397	void stroke_circle(Canvas *c, const struct XshimGC *gc, int x, int y, unsigned w) {
398	  const int lw = gc->line_width;
399	  const uint16_t colour = (uint16_t)gc->foreground;
400	  g_alpha = gc->alpha;
401	  const float o = centre_offset(lw);
402	  const float radius = (float)w / 2.0f;
403	  const float cx = (float)x + radius + o, cy = (float)y + radius + o;
404	  const float outer = radius + (float)lw / 2.0f;
405	  const float inner = radius - (float)lw / 2.0f;
406	  const wide_t y0 = max_w(0, (wide_t)floorf(cy - outer));
407	  const wide_t y1 = min_w((wide_t)c->h - 1, (wide_t)ceilf(cy + outer));
408	  for (wide_t row = y0; row <= y1; row++) {
409	    const float dy = (float)row + 0.5f - cy;
410	    if (fabsf(dy) >= outer) continue;
411	    const float ho = sqrtf(outer * outer - dy * dy);
412	    const wide_t xo0 = (wide_t)ceilf(cx - ho - 0.5f);
413	    const wide_t xo1 = (wide_t)floorf(cx + ho - 0.5f);
414	    if (inner <= 0.0f || fabsf(dy) >= inner) {
415	      fill_box(c, xo0, row, xo1, row, colour);
416	      continue;
417	    }
418	    const float hi = sqrtf(inner * inner - dy * dy);
